# -*- coding: utf-8 -*-
"""
Step 1 - Assemble the GRU input tables for the climate runs from the outputs
of Module 1 (bias-corrected basin-average GCM forcing) and Module 2 (HEC-HMS
simulated outlet discharge).

    Date, precip, tmin, tmax, srad, simdischarge

--forcing paper       (default) equal-weight mean of the bias-corrected GCM
                      series used in the paper:
                      ../1. GCM ranking and bias correction/DataGRU/*_BiasCorrected.csv
--forcing reproduced  RS-weighted ensemble regenerated by Module 1:
                      ../1. GCM ranking and bias correction/Ensemble/Ensemble_<ssp>.csv

simdischarge is taken from ../2. HEC-HMS/Results/HMS_Outlet_Q_<Scenario>.csv
when that file exists (after running HEC-HMS in Module 2); otherwise the
column of the table used in the paper (Data/Inputs/) is kept.

Module 1 provides SSP series only (2015-2099); for the Historical scenario the
forcing columns of Data/Inputs/Historical_EnsembleMean.csv are kept.

Output : Data/Inputs_rebuilt/<Scenario>_EnsembleMean.csv
         Results/GRU_inputs_comparison.csv  (rebuilt vs Data/Inputs)
To use the rebuilt tables in step 4, set INPUT_DIR in common.py to
DATA_DIR / "Inputs_rebuilt".

Run    : python 01_build_gru_inputs.py [--forcing paper|reproduced]
"""

import argparse

import numpy as np
import pandas as pd

from common import DATA_DIR, FORCING, INPUT_DIR, MODULE1_DIR, MODULE2_DIR, RESULTS_DIR, SCENARIOS, read_csv

OUT_DIR = DATA_DIR / "Inputs_rebuilt"
PREFIX = {"precip": "PR", "tmin": "TASMIN", "tmax": "TASMAX", "srad": "RSDS"}
ENS_COL = {"precip": "pr", "tmin": "tasmin", "tmax": "tasmax", "srad": "rsds"}


def forcing_paper(ssp):
    """Equal-weight mean of the available bias-corrected GCM series (DataGRU/)."""
    d = MODULE1_DIR / "DataGRU"
    cols = {}
    for var in FORCING:
        files = sorted(d.glob(f"{PREFIX[var]}_Areal_{ssp}_*_BiasCorrected.csv"))
        if not files:
            raise FileNotFoundError(f"No {PREFIX[var]} files for {ssp} in {d}")
        series = [pd.read_csv(f, parse_dates=["Date"]).set_index("Date").drop(columns="Raw", errors="ignore").iloc[:, 0]
                  for f in files]
        cols[var] = pd.concat(series, axis=1).mean(axis=1)
    return pd.DataFrame(cols)


def forcing_reproduced(ssp):
    f = MODULE1_DIR / "Ensemble" / f"Ensemble_{ssp}.csv"
    if not f.exists():
        raise FileNotFoundError(f"{f} not found - run Module 1 (04_weighted_ensemble.py) first")
    e = read_csv(f)
    return pd.DataFrame({v: e[ENS_COL[v]] for v in FORCING})


def main(source="paper"):
    OUT_DIR.mkdir(exist_ok=True)
    RESULTS_DIR.mkdir(exist_ok=True)
    rows = []
    for scen in SCENARIOS:
        used = read_csv(INPUT_DIR / f"{scen}_EnsembleMean.csv")
        if scen == "Historical":
            forcing, f_note = used[FORCING].copy(), "kept from Data/Inputs"
        else:
            ssp = scen.lower()
            try:
                forcing = (forcing_paper if source == "paper" else forcing_reproduced)(ssp)
                f_note = f"Module 1 ({source})"
            except FileNotFoundError as err:
                print(f"[NOTE] {err}\n       -> forcing kept from Data/Inputs for {scen}")
                forcing, f_note = used[FORCING].copy(), "kept from Data/Inputs"
        hms_file = MODULE2_DIR / "Results" / f"HMS_Outlet_Q_{scen}.csv"
        if hms_file.exists():
            q = read_csv(hms_file)["Q_HMS_m3s"].rename("simdischarge")
            q_note = "Module 2 HEC-HMS run"
        else:
            q, q_note = used["simdischarge"], "kept from Data/Inputs"
        out = forcing.join(q, how="inner").dropna()
        out.index.name = "Date"
        out.reset_index().to_csv(OUT_DIR / f"{scen}_EnsembleMean.csv", index=False)

        common = out.index.intersection(used.index)
        row = {"Scenario": scen, "Forcing": f_note, "simdischarge": q_note,
               "Start": out.index.min().date(), "End": out.index.max().date()}
        for c in FORCING + ["simdischarge"]:
            row[f"{c}_mean_rebuilt"] = out.loc[common, c].mean()
            row[f"{c}_mean_paper"] = used.loc[common, c].mean()
            row[f"{c}_max_abs_diff"] = float(np.abs(out.loc[common, c] - used.loc[common, c]).max())
        rows.append(row)
        print(f"{scen:<10} forcing: {f_note:<26} simdischarge: {q_note:<24} -> Inputs_rebuilt/ "
              f"(max |diff| vs paper: " +
              ", ".join(f"{c} {row[f'{c}_max_abs_diff']:.3g}" for c in FORCING + ["simdischarge"]) + ")")
    pd.DataFrame(rows).round(4).to_csv(RESULTS_DIR / "GRU_inputs_comparison.csv", index=False)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--forcing", choices=["paper", "reproduced"], default="paper")
    main(ap.parse_args().forcing)
